// Outward unit normal for each face, in world (cube) space.
export const FACE_NORMALS = {
  U: new THREE.Vector3(0, 1, 0),
  D: new THREE.Vector3(0, -1, 0),
  L: new THREE.Vector3(-1, 0, 0),
  R: new THREE.Vector3(1, 0, 0),
  F: new THREE.Vector3(0, 0, 1),
  B: new THREE.Vector3(0, 0, -1),
};

// Standard western color scheme.
const FACE_COLORS = {
  U: '#ffffff', // white
  D: '#ffd500', // yellow
  L: '#ff8c00', // orange
  R: '#c41e3a', // red
  F: '#009e60', // green
  B: '#0051ba', // blue
};

// Grid orientation per face: row/col direction vectors so that
// stickerAt(cube, face, row, col) with row,col in {0,1,2} is well defined.
const GRID = {
  U: { rowDir: new THREE.Vector3(0, 0, 1), colDir: new THREE.Vector3(1, 0, 0) },
  D: { rowDir: new THREE.Vector3(0, 0, -1), colDir: new THREE.Vector3(1, 0, 0) },
  F: { rowDir: new THREE.Vector3(0, -1, 0), colDir: new THREE.Vector3(1, 0, 0) },
  B: { rowDir: new THREE.Vector3(0, -1, 0), colDir: new THREE.Vector3(-1, 0, 0) },
  R: { rowDir: new THREE.Vector3(0, -1, 0), colDir: new THREE.Vector3(0, 0, -1) },
  L: { rowDir: new THREE.Vector3(0, -1, 0), colDir: new THREE.Vector3(0, 0, 1) },
};

const EPS = 1e-6;

function snapToInt(v) {
  v.set(Math.round(v.x), Math.round(v.y), Math.round(v.z));
  return v;
}

function vecEquals(a, b) {
  return a.x === b.x && a.y === b.y && a.z === b.z;
}

/**
 * Build the cube: 26 cubie meshes at integer offsets in {-1,0,1}^3 minus the
 * center. Each cubie carries:
 *   userData.home     - Vector3, its original integer position
 *   userData.stickers - array of { dir: Vector3, color: string } for every
 *                       outward-facing side at build time; `dir` lives in the
 *                       cubie's local frame and is rotated along with the
 *                       cubie quaternion on every turn.
 */
export function buildCube() {
  const group = new THREE.Group();
  const geometry = new THREE.BoxGeometry(0.96, 0.96, 0.96);

  for (let x = -1; x <= 1; x++) {
    for (let y = -1; y <= 1; y++) {
      for (let z = -1; z <= 1; z++) {
        if (x === 0 && y === 0 && z === 0) continue;

        const stickers = [];
        const pos = new THREE.Vector3(x, y, z);
        for (const [face, n] of Object.entries(FACE_NORMALS)) {
          if (pos.dot(n) === 1) {
            stickers.push({ dir: n.clone(), color: FACE_COLORS[face] });
          }
        }

        const material = new THREE.MeshLambertMaterial({ color: '#111111' });
        const cubie = new THREE.Mesh(geometry, material);
        cubie.position.copy(pos);
        cubie.userData.home = pos.clone();
        cubie.userData.stickers = stickers;
        group.add(cubie);
      }
    }
  }
  return group;
}

/** The cubie currently occupying integer position `pos`. */
export function cubieAt(cube, pos) {
  return cube.children.find((m) => vecEquals(m.position, pos));
}

/**
 * Turn a face: rotate the 9 cubies whose position satisfies pos·n == 1 by
 * quarterTurns * PI/2 clockwise about the face normal n (as seen from outside
 * the face). Positions are snapped back to integers, quaternions are composed,
 * and each cubie's sticker directions are rotated in lockstep.
 */
export function turnFace(cube, face, quarterTurns = 1) {
  const n = FACE_NORMALS[face];
  if (!n) throw new Error(`unknown face: ${face}`);
  if (!Number.isInteger(quarterTurns)) throw new Error('quarterTurns must be an integer');

  // Clockwise viewed from outside the face => negative angle about n.
  const q = new THREE.Quaternion().setFromAxisAngle(n, (-quarterTurns * Math.PI) / 2);

  const layer = cube.children.filter((m) => Math.round(m.position.dot(n)) === 1);
  for (const m of layer) {
    m.position.applyQuaternion(q);
    snapToInt(m.position);
    m.quaternion.premultiply(q).normalize();
    for (const s of m.userData.stickers) {
      s.dir.applyQuaternion(q);
      snapToInt(s.dir);
    }
  }
}

const KEY_TO_VEC = Object.fromEntries(
  Object.entries(GRID).map(([face, { rowDir, colDir }]) => [
    face,
    {
      n: FACE_NORMALS[face],
      rowDir,
      colDir,
    },
  ]),
);

/**
 * Color of the sticker visible at grid cell (row, col) ∈ {0,1,2}² of `face`.
 * Maps the grid cell to its integer cubie position, then finds which of that
 * cubie's tracked stickers currently points along the face normal.
 */
export function stickerAt(cube, face, row, col) {
  const g = KEY_TO_VEC[face];
  if (!g) throw new Error(`unknown face: ${face}`);
  if (!Number.isInteger(row) || !Number.isInteger(col) || row < 0 || row > 2 || col < 0 || col > 2) {
    throw new Error(`row/col out of range: ${row}, ${col}`);
  }

  const target = g.n
    .clone()
    .addScaledVector(g.rowDir, row - 1)
    .addScaledVector(g.colDir, col - 1);

  const cubie = cubieAt(cube, target);
  if (!cubie) throw new Error(`no cubie at ${target.toArray()}`);

  const sticker = cubie.userData.stickers.find((s) => vecEquals(s.dir, g.n));
  return sticker ? sticker.color : null;
}
